local StarterGui = game:GetService("StarterGui")
local confirmed = false

local bind = Instance.new("BindableFunction")
function bind.OnInvoke(choice)
	if choice == "Continue" then
		confirmed = true
	else
		confirmed = false
	end
end

StarterGui:SetCore("SendNotification", {
	Title = "Warning",
	Text = "Loading this script will freeze your game for ~6 seconds. Continue?",
	Duration = 10,
	Button1 = "Continue",
	Button2 = "No",
	Callback = bind
})
repeat task.wait() until confirmed == true
